contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        uint preCBalance = address(c).balance;
        uint preTestBalance = address(this).balance;

        bool reverted;
        c.withdraw(amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        uint postCBalance = address(c).balance;
        uint postTestBalance = address(this).balance;

        assert((!reverted && postCBalance + amount == preCBalance && postTestBalance == preTestBalance + amount)
            || (reverted && postCBalance == preCBalance && postTestBalance == preTestBalance));
    }
}

